function plot_gate3e_r2_stats()    projectRoot = pwd();    inRoot = fullfile(projectRoot, 'results', 'paper_phenotypes', 'kao_vs_naive', 'dimensionality_alignment');    d = load(fullfile(inRoot, 'gate3e_r2_data.mat'));    epochs = {'Prep', 'Move'};    PR_delta = d.PR_Naive - d.PR_Kao;    Align_deficit = d.Align_Exp - d.Align_Obs;    rng(1234, 'twister');    nBoot = 10000;    % Bootstrapping functions    [pr_med, pr_se, pr_p_raw, pr_p_adj] = compute_stats(PR_delta, nBoot);    [al_med, al_se, al_p_raw, al_p_adj] = compute_stats(Align_deficit, nBoot);    [pr_kao_med, pr_kao_se, ~, ~] = compute_stats(d.PR_Kao, nBoot);    [pr_naive_med, pr_naive_se, ~, ~] = compute_stats(d.PR_Naive, nBoot);    [al_obs_med, al_obs_se, ~, ~] = compute_stats(d.Align_Obs, nBoot);    [al_exp_med, al_exp_se, ~, ~] = compute_stats(d.Align_Exp, nBoot);    disp('=== PR Delta (Naive - Kao) ===');    print_stats(epochs, pr_med, pr_se, pr_p_raw, pr_p_adj);    disp('=== Alignment Deficit (Exp - Obs) ===');    print_stats(epochs, al_med, al_se, al_p_raw, al_p_adj);    plot_main_fig(epochs, pr_med, pr_se, pr_p_adj, al_med, al_se, al_p_adj, projectRoot);    plot_supp_fig(epochs, pr_kao_med, pr_kao_se, pr_naive_med, pr_naive_se, ...        al_obs_med, al_obs_se, al_exp_med, al_exp_se, projectRoot);endfunction [meds, ses, p_raw, p_adj] = compute_stats(data, nBoot)    % data is 10 x 2    [N, E] = size(data);    boot_meds = zeros(nBoot, E);    for b = 1:nBoot        samp = randi(N, N, 1);        boot_meds(b, :) = median(data(samp, :), 1);    end    meds = median(data, 1)';    ses = std(boot_meds, 0, 1)';    p_raw = zeros(3, 1);    % vs zero    for e = 1:E        p_raw(e) = 2 * min(mean(boot_meds(:, e) <= 0), mean(boot_meds(:, e) >= 0));    end    % pairwise (Prep vs Move)    diff_boot = boot_meds(:, 2) - boot_meds(:, 1);    p_raw(3) = 2 * min(mean(diff_boot <= 0), mean(diff_boot >= 0));    p_adj = bh_correct(p_raw);endfunction p_adj = bh_correct(p)    p = p(:);    n = numel(p);    [p_sort, idx] = sort(p);    p_adj_sort = p_sort .* n ./ (1:n)';    for i = n-1:-1:1        p_adj_sort(i) = min(p_adj_sort(i), p_adj_sort(i+1));    end    p_adj_sort = min(p_adj_sort, 1);    p_adj = zeros(size(p));    p_adj(idx) = p_adj_sort;endfunction print_stats(epochs, meds, ses, p_raw, p_adj)    for e = 1:2        fprintf('%s: %.3f +/- %.3f (p_raw=%.4f, p_adj=%.4f)\n', epochs{e}, meds(e), ses(e), p_raw(e), p_adj(e));    end    fprintf('Move vs Prep: p_raw=%.4f, p_adj=%.4f\n', p_raw(3), p_adj(3));endfunction sym = get_stars(p)    if p < 0.001, sym = '***';    elseif p < 0.01, sym = '**';    elseif p < 0.05, sym = '*';    else, sym = 'ns'; endendfunction plot_main_fig(epochs, pr_med, pr_se, pr_p_adj, al_med, al_se, al_p_adj, projectRoot)    fig = figure('Position', [100, 100, 600, 350], 'Color', 'w');    t = tiledlayout(1, 2, 'TileSpacing', 'compact', 'Padding', 'compact');    ax1 = nexttile; hold on;    yline(0, 'k--', 'LineWidth', 1);    errorbar(1:2, pr_med, pr_se, 'ko-', 'LineWidth', 1.5, 'MarkerFaceColor', 'k');    ylabel('\Delta PR (Naive - Kao)');    title('a. Dimensionality Expansion');    xticks(1:2); xticklabels(epochs);    xlim([0.5, 2.5]);    add_significance(ax1, pr_p_adj, pr_med);    ax2 = nexttile; hold on;    yline(0, 'k--', 'LineWidth', 1);    errorbar(1:2, al_med, al_se, 'ko-', 'LineWidth', 1.5, 'MarkerFaceColor', 'k');    ylabel('Alignment Deficit (%)');    title('b. Cross-Condition Alignment Deficit');    xticks(1:2); xticklabels(epochs);    xlim([0.5, 2.5]);    add_significance(ax2, al_p_adj, al_med);    set([ax1 ax2], 'FontSize', 12, 'TickDir', 'out', 'LineWidth', 0.3, 'XColor', [0 0 0], 'YColor', [0 0 0]);    grid([ax1 ax2], 'off');    box([ax1 ax2], 'off');    outDirP = fullfile(projectRoot, 'plots', 'paper_phenotypes', 'kao_vs_naive', 'dimensionality_alignment', 'png');    outDirF = fullfile(projectRoot, 'plots', 'paper_phenotypes', 'kao_vs_naive', 'dimensionality_alignment', 'fig');    saveas(fig, fullfile(outDirP, 'gate3e_r2_main.png'));    savefig(fig, fullfile(outDirF, 'gate3e_r2_main.fig'));endfunction add_significance(ax, p_adj, med)    yMax = max(med) + 0.1 * abs(max(med));    if yMax < 0, yMax = 0.05 * max(abs(med)); end    for e = 1:2        if p_adj(e) < 0.05            text(e, med(e) + 0.05 * max(abs(med)) + 0.01, get_stars(p_adj(e)), 'HorizontalAlignment', 'center', 'FontSize', 14);        end    end    yline_pos = yMax + 0.1 * max(abs(med));    if p_adj(3) < 0.05        plot([1 2], [yline_pos yline_pos], 'k-', 'LineWidth', 1);        text(1.5, yline_pos + 0.02 * max(abs(med)), get_stars(p_adj(3)), 'HorizontalAlignment', 'center', 'FontSize', 14);        yline_pos = yline_pos + 0.1 * max(abs(med));    end    ylim([min(med)-0.1*max(abs(med))-0.1, yline_pos]);endfunction plot_supp_fig(epochs, pr_kao_m, pr_kao_se, pr_naive_m, pr_naive_se, al_obs_m, al_obs_se, al_exp_m, al_exp_se, projectRoot)    fig = figure('Position', [100, 500, 600, 350], 'Color', 'w');    t = tiledlayout(1, 2, 'TileSpacing', 'compact', 'Padding', 'compact');    colorKao = [0.1, 0.5, 0.8];    colorNaive = [0.8, 0.3, 0.2];    colorObs = [0.3, 0.3, 0.3];    colorExp = [0.7, 0.7, 0.7];    x = 1:2;    ax1 = nexttile; hold on;    errorbar(x - 0.1, pr_kao_m, pr_kao_se, 'o-', 'Color', colorKao, 'MarkerFaceColor', colorKao, 'LineWidth', 1.5, 'DisplayName', 'Kao');    errorbar(x + 0.1, pr_naive_m, pr_naive_se, 'o-', 'Color', colorNaive, 'MarkerFaceColor', colorNaive, 'LineWidth', 1.5, 'DisplayName', 'Naive feedforward');    ylabel('Participation Ratio');    title('a. Condition-specific Dimensionality');    xticks(x); xticklabels(epochs); xlim([0.5, 2.5]);    legend('Location', 'best', 'box', 'off');    ax2 = nexttile; hold on;    errorbar(x - 0.1, al_exp_m, al_exp_se, 'o-', 'Color', colorExp, 'MarkerFaceColor', colorExp, 'LineWidth', 1.5, 'DisplayName', 'Expected (Null)');    errorbar(x + 0.1, al_obs_m, al_obs_se, 'o-', 'Color', colorObs, 'MarkerFaceColor', colorObs, 'LineWidth', 1.5, 'DisplayName', 'Observed');    ylabel('Alignment (%)');    title('b. Observed vs Expected Alignment');    xticks(x); xticklabels(epochs); xlim([0.5, 2.5]);    legend('Location', 'best', 'box', 'off');    set([ax1 ax2], 'FontSize', 12, 'TickDir', 'out', 'LineWidth', 0.3, 'XColor', [0 0 0], 'YColor', [0 0 0]);    grid([ax1 ax2], 'off');    box([ax1 ax2], 'off');    outDirP = fullfile(projectRoot, 'plots', 'paper_phenotypes', 'kao_vs_naive', 'dimensionality_alignment', 'png');    outDirF = fullfile(projectRoot, 'plots', 'paper_phenotypes', 'kao_vs_naive', 'dimensionality_alignment', 'fig');    saveas(fig, fullfile(outDirP, 'gate3e_r2_supp.png'));    savefig(fig, fullfile(outDirF, 'gate3e_r2_supp.fig'));end
